import sys,json,codecs,unicodedata
rows=json.load(sys.stdin)
result=[]
for row in rows:
    factory=codecs.getincrementaldecoder(row['encoding'])
    decoder=factory(row['errors'])
    events=[]
    for step in row['steps']:
        try: event={'text':list(map(ord,decoder.decode(bytes(step['bytes']),step['final'])))}
        except UnicodeDecodeError as e: event={'error':[e.encoding,list(e.object),e.start,e.end,e.reason]}
        pending,state=decoder.getstate()
        event['state']=[list(pending),str(state)]
        events.append(event)
        if step['reset']: decoder.reset()
        else:
            decoder=factory(row['errors'])
            decoder.setstate((pending,state))
    result.append(events)
json.dump({'version':sys.version,'unicode':unicodedata.unidata_version,'platform':sys.platform,'byteorder':sys.byteorder,'results':result},sys.stdout)
